import unittest

from ledger import reconcile


class ReconcileTests(unittest.TestCase):
    def test_sequence_and_kinds(self) -> None:
        events = [
            {"id": "3", "account": "cash", "kind": "debit", "amount": 4, "sequence": 3},
            {"id": "1", "account": "cash", "kind": "credit", "amount": 10, "sequence": 1},
            {"id": "2", "account": "fees", "kind": "credit", "amount": 2, "sequence": 2},
        ]
        self.assertEqual(reconcile(events), {"cash": 6, "fees": 2})

    def test_duplicate_id_is_rejected(self) -> None:
        events = [
            {"id": "same", "account": "a", "kind": "credit", "amount": 1, "sequence": 1},
            {"id": "same", "account": "b", "kind": "credit", "amount": 2, "sequence": 2},
        ]
        with self.assertRaises(ValueError):
            reconcile(events)


